import heapq

def k_smallest_pairs(nums1, nums2, k):
    if not nums1 or not nums2 or k == 0:
        return []

    # Use a heap to keep track of the smallest pairs
    heap = []
    for i in range(min(len(nums1), k)):
        for j in range(min(len(nums2), k)):
            if len(heap) < k:
                # Push the sum and the pair into the heap
                heapq.heappush(heap, (nums1[i] + nums2[j], [nums1[i], nums2[j]]))
            else:
                # If the current sum is greater than the smallest in the heap, break
                if nums1[i] + nums2[j] > heap[0][0]:
                    break

    # Extract the pairs from the heap
    return [heapq.heappop(heap)[1] for _ in range(len(heap))]

